""","""import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import type {ExtWebSocket} from './connectionHandler.js';
""",1)
old="""export function createMessageHandler(orchestrator: ChatOrchestrator) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
  };
}
"""
new="""export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // Frames answered off the lock, still in arrival order per socket: a ping sent after a list_sessions is answered after it.
  const outOfTurn = new WeakMap<WebSocket, Promise<void>>();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    const answer = () => wsErrorHandler(ws, async () => answerOutOfTurn(ws, sessionStore, validation));
    const pending = outOfTurn.get(ws);
    const answered = pending ? pending.then(answer) : answer();
    outOfTurn.set(ws, answered);
    const settle = () => {
      if (outOfTurn.get(ws) === answered) outOfTurn.delete(ws);
    };
    answered.then(settle, settle);
    return answered;
  };
}

// A history request is not a turn: it mutates nothing, so it never queues behind a streaming answer.
async function answerOutOfTurn(
  ws: WebSocket,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (validation.valid && validation.data.type === 'list_sessions') {
    return answerListSessions(ws, sessionStore, validation.data);
  }
  answerFrame(ws, validation);
}

// The user is the connection's, never the frame's: the validator has already dropped any userId a client sent.
async function answerListSessions(
  ws: WebSocket,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  const {userId} = ws as ExtWebSocket;
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  let summaries: SessionSummary[];
  try {
    summaries = await sessionStore.listFor(userId, {limit: message.limit, before: message.before});
  } catch (error) {
    log.error('ws', 'session list failed', {userId, error: error instanceof Error ? error.message : 'Unknown error'});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
    return;
  }
  sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
}

// Dates go out as ISO strings: a Date does not survive JSON.stringify as a Date.
function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}
"""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
